import React, { useState, useEffect } from 'react';
import SearchBar from './components/SearchBar';
import ResultsList from './components/ResultsList';
import SimilarBooks from './components/SimilarBooks';
import BookBackground from './components/BookBackground';
import './App.css';

const API_URL = "http://localhost:5000/api";

// Composant pour les particules de poussière flottantes
function DustParticles() {
  return (
    <div className="dust-container">
      {[...Array(30)].map((_, i) => (
        <div 
          key={i} 
          className="dust-particle"
          style={{
            left: `${Math.random() * 100}%`,
            animationDelay: `${Math.random() * 15}s`,
            animationDuration: `${15 + Math.random() * 20}s`,
          }}
        />
      ))}
    </div>
  );
}

// Composant lampe de musée
function MuseumLamp() {
  return (
    <div className="museum-lamp">
      <div className="lamp-fixture"></div>
      <div className="lamp-light"></div>
    </div>
  );
}

function App() {
  const [results, setResults] = useState([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);
  const [searchPerformed, setSearchPerformed] = useState(false);
  const [similarBooks, setSimilarBooks] = useState([]);
  const [showSimilar, setShowSimilar] = useState(false);
  const [selectedBookTitle, setSelectedBookTitle] = useState('');
  const [showWelcome, setShowWelcome] = useState(true);

  useEffect(() => {
    const timer = setTimeout(() => setShowWelcome(false), 3000);
    return () => clearTimeout(timer);
  }, []);

  const handleSearch = async (query) => {
    if (!query.trim()) return;
    
    setLoading(true);
    setError(null);
    setSearchPerformed(true);
    setShowSimilar(false);
    
    try {
      const response = await fetch(`${API_URL}/search?q=${encodeURIComponent(query)}`);
      if (!response.ok) throw new Error('Erreur serveur');
      const data = await response.json();
      setResults(data);
    } catch (err) {
      setError('Erreur: Vérifie que le Backend Flask est bien lancé sur le port 5000.');
      setResults([]);
    } finally {
      setLoading(false);
    }
  };

  const handleGetSimilar = async (bookId, bookTitle) => {
    try {
      const response = await fetch(`${API_URL}/similar/${bookId}`);
      if (!response.ok) throw new Error('Erreur serveur');
      const data = await response.json();
      setSimilarBooks(data);
      setSelectedBookTitle(bookTitle);
      setShowSimilar(true);
    } catch (err) {
      alert('Erreur lors de la récupération des recommandations.');
    }
  };

  const closeSimilarModal = () => {
    setShowSimilar(false);
    setSimilarBooks([]);
  };

  return (
    <div className="app">
      {/* Écran de bienvenue */}
      <div className={`welcome-screen ${showWelcome ? 'visible' : 'hidden'}`}>
        <div className="welcome-content">
          <div className="welcome-icon">🏛️</div>
          <h1>Bienvenue au Musée des Livres</h1>
          <p>Entrez dans notre collection...</p>
          <div className="welcome-doors">
            <div className="door left"></div>
            <div className="door right"></div>
          </div>
        </div>
      </div>

      <BookBackground />
      <DustParticles />
      
      {/* Cadre de musée */}
      <div className="museum-frame">
        <div className="frame-corner top-left"></div>
        <div className="frame-corner top-right"></div>
        <div className="frame-corner bottom-left"></div>
        <div className="frame-corner bottom-right"></div>
      </div>

      <div className="container">
        <MuseumLamp />
        
        <header className="header">
          <div className="museum-plaque">
            <div className="plaque-ornament left">❧</div>
            <h1 className="title">
              <span className="title-line">Le Musée</span>
              <span className="title-main">des Livres Anciens</span>
            </h1>
            <div className="plaque-ornament right">❧</div>
          </div>
          <p className="subtitle">
            <span className="subtitle-decoration">✦</span>
            Collection Permanente — Depuis 1850
            <span className="subtitle-decoration">✦</span>
          </p>
          <div className="museum-info">
            <span className="info-item">📖 644 Ouvrages</span>
            <span className="info-divider">|</span>
            <span className="info-item">🏆 Éditions Rares</span>
            <span className="info-divider">|</span>
            <span className="info-item">🌍 Collection Mondiale</span>
          </div>
        </header>

        <div className="search-section">
          <div className="section-plaque">
            <span>🔍 Catalogue de Recherche</span>
          </div>
          <SearchBar onSearch={handleSearch} loading={loading} />
        </div>

        {error && (
          <div className="error-message">
            <span className="error-icon">⚠️</span>
            {error}
          </div>
        )}

        {loading && (
          <div className="loading">
            <div className="loading-book">
              <div className="book-page"></div>
              <div className="book-page"></div>
              <div className="book-page"></div>
            </div>
            <p>Consultation des archives...</p>
          </div>
        )}

        {!loading && searchPerformed && (
          <div className="results-section">
            <div className="section-plaque results-plaque">
              <span>📜 Œuvres Découvertes</span>
            </div>
            <ResultsList 
              results={results} 
              onGetSimilar={handleGetSimilar} 
            />
          </div>
        )}

        {showSimilar && (
          <SimilarBooks 
            books={similarBooks} 
            bookTitle={selectedBookTitle}
            onClose={closeSimilarModal} 
          />
        )}

        <footer className="museum-footer">
          <div className="footer-ornament">❦</div>
          <p>Musée des Livres Anciens — Tous droits réservés</p>
          <p className="footer-quote">"Un livre est un jardin que l'on porte dans sa poche"</p>
        </footer>
      </div>
    </div>
  );
}

export default App;
